    private final List<Employee> allEmployees;
    private int employeeCounter;
    private Manager ceo;

    private Company() {
        allEmployees = new ArrayList<>();
        employeeCounter = 1;
    }

    public static Company getInstance() {
        return instance;
    }

    public void hireCEO(Manager manager) {
        Objects.requireNonNull(manager, "CEO cannot be null");

        if (ceo != null) {
            throw new IllegalStateException("A CEO has already been hired");
        }

        manager.setId("EMP-" + employeeCounter++);
        ceo = manager;
        allEmployees.add(manager);
    }

    public Manager getCEO() {
        return ceo;
    }
}

