import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public class AdvancedFileProcessor {
    private final Path directory;

    public AdvancedFileProcessor(String directoryPath) {
        if (directoryPath == null || directoryPath.isBlank()) {
            throw new IllegalArgumentException("Directory path must not be null or blank.");
        }

        try {
            this.directory = Paths.get(directoryPath);
        } catch (RuntimeException e) {
            throw new IllegalArgumentException("Invalid directory path.", e);
        }

        if (!Files.isDirectory(this.directory)) {
            throw new IllegalArgumentException("Provided path is not a directory.");
        }
    }

    public Map<String, Object> processFiles() {
        int fileCount = 0;
        long totalSize = 0L;
        Path largestFile = null;
        long largestFileSize = -1L;

        try {
            try (var files = Files.walk(directory)) {
                for (Path file : (Iterable<Path>) files::iterator) {
                    if (Files.isRegularFile(file)) {
                        long fileSize = Files.size(file);
                        fileCount++;
                        totalSize += fileSize;

                        if (fileSize > largestFileSize) {
                            largestFileSize = fileSize;
                            largestFile = file;
                        }
                    }
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to process files.", e);
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", largestFile);
        result.put("wordFrequency", Collections.emptyMap());

        return result;
    }
}

