import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private final Path directory;

    public AdvancedFileProcessor(String directoryPath) {
        try {
            this.directory = Paths.get(directoryPath);
        } catch (InvalidPathException | NullPointerException e) {
            throw new IllegalArgumentException("Invalid directory path", e);
        }

        if (!Files.isDirectory(this.directory)) {
            throw new IllegalArgumentException("Provided path is not a directory");
        }
    }

    public Map<String, Object> processFiles() {
        long fileCount = 0;
        long totalSize = 0;
        long largestSize = -1;
        String largestFile = "N/A";

        try (Stream<Path> paths = Files.walk(directory)) {
            for (Path path : (Iterable<Path>) paths.filter(Files::isRegularFile)::iterator) {
                long fileSize = Files.size(path);

                fileCount++;
                totalSize += fileSize;

                if (fileSize > largestSize) {
                    largestSize = fileSize;
                    largestFile = path.getFileName().toString();
                }
            }
        } catch (IOException e) {
            throw new IllegalStateException("Failed to process files", e);
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", largestFile);
        result.put("wordFrequency", Collections.emptyMap());

        return result;
    }
}

