import java.util.Map;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private final Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        if (directoryPath == null) {
            throw new IllegalArgumentException("Directory path cannot be null.");
        }

        this.directoryPath = Paths.get(directoryPath);

        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory.");
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> results = new LinkedHashMap<>();
        Map<String, Integer> wordFrequency = new LinkedHashMap<>();

        int fileCount = 0;
        long totalSize = 0L;
        long largestSize = -1L;
        String largestFile = "N/A";

        try (Stream<Path> files = Files.walk(directoryPath)) {
            for (Path file : (Iterable<Path>) files::iterator) {
                if (!Files.isRegularFile(file)) {
                    continue;
                }

                fileCount++;

                try {
                    long fileSize = Files.size(file);
                    totalSize += fileSize;

                    if (fileSize > largestSize) {
                        largestSize = fileSize;
                        largestFile = file.getFileName().toString();
                    }

                    processFileContent(file, wordFrequency);
                } catch (IOException ignored) {
                    // Ignore files that cannot be read or whose metadata is unavailable.
                }
            }
        } catch (IOException ignored) {
            // Return the statistics collected before the directory traversal failed.
        }

        results.put("fileCount", fileCount);
        results.put("totalSize", totalSize);
        results.put("largestFile", largestFile);
        results.put("wordFrequency", wordFrequency);

        return results;
    }

    private void processFileContent(Path file, Map<String, Integer> wordFrequency) {
        try {
            String content = new String(
                    Files.readAllBytes(file),
                    StandardCharsets.UTF_8
            );

            String[] words = content.split("\\s+");

            for (String word : words) {
                String normalizedWord = word
                        .toLowerCase(Locale.ROOT)
                        .replaceAll("[^a-z]", "");

                if (!normalizedWord.isEmpty()) {
                    wordFrequency.put(
                            normalizedWord,
                            wordFrequency.getOrDefault(normalizedWord, 0) + 1
                    );
                }
            }
        } catch (IOException ignored) {
            // Ignore files that cannot be read.
        }
    }
}

