import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private final Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        if (directoryPath == null) {
            throw new IllegalArgumentException("Directory path cannot be null.");
        }

        this.directoryPath = Paths.get(directoryPath);

        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory.");
        }
    }

    public Map<String, Object> processFiles() {
        int fileCount = 0;
        long totalSize = 0L;
        long largestSize = -1L;
        String largestFile = "N/A";
        Map<String, Integer> wordFrequency = new HashMap<>();

        try (Stream<Path> files = Files.walk(directoryPath)) {
            for (Path file : (Iterable<Path>) files.filter(Files::isRegularFile)::iterator) {
                long fileSize = Files.size(file);

                fileCount++;
                totalSize += fileSize;

                if (fileSize > largestSize) {
                    largestSize = fileSize;
                    largestFile = file.getFileName().toString();
                }

                processFileContent(file, wordFrequency);
            }
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to process files.", e);
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", largestFile);
        result.put("wordFrequency", sortByValue(wordFrequency));

        return result;
    }

    private void processFileContent(Path file, Map<String, Integer> wordFrequency) {
        try {
            String content = Files.readString(file);
            String[] words = content.split("\\s+");

            for (String word : words) {
                String cleanedWord = word
                        .replaceAll("[^a-zA-Z]", "")
                        .toLowerCase();

                if (!cleanedWord.isEmpty()) {
                    wordFrequency.merge(cleanedWord, 1, Integer::sum);
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to read file: " + file, e);
        }
    }

    private Map<String, Integer> sortByValue(Map<String, Integer> map) {
        return map.entrySet()
                .stream()
                .sorted(
                        Map.Entry.<String, Integer>comparingByValue(Comparator.reverseOrder())
                                .thenComparing(Map.Entry.comparingByKey())
                )
                .collect(
                        LinkedHashMap::new,
                        (sortedMap, entry) -> sortedMap.put(entry.getKey(), entry.getValue()),
                        LinkedHashMap::putAll
                );
    }
}

