import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Observable;
import java.util.Set;

public class NavalBattleAdapter extends Observable {
    private final Set<String> shipPositions;
    private final Set<String> attackPositions;
    private boolean gameOver;
    private String winner;

    public NavalBattleAdapter() {
        this.shipPositions = new LinkedHashSet<>();
        this.attackPositions = new LinkedHashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    public NavalBattleAdapter(List<String> shipPositions, List<String> attackPositions) {
        this();

        if (shipPositions != null) {
            for (String coordinate : shipPositions) {
                validateCoordinate(coordinate);
                this.shipPositions.add(coordinate);
            }
        }

        if (attackPositions != null) {
            for (String coordinate : attackPositions) {
                validateCoordinate(coordinate);
                this.attackPositions.add(coordinate);
            }
        }
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null || coordinates.isEmpty()) {
            throw new IllegalArgumentException("Coordinates must not be null or empty");
        }

        for (String coordinate : coordinates) {
            validateCoordinate(coordinate);
            shipPositions.add(coordinate);
        }

        gameOver = false;
        winner = null;
        notifyStateChange("SHIPS_PLACED");
    }

    public HitResult receiveAttack(String coordinate) {
        validateCoordinate(coordinate);
        attackPositions.add(coordinate);

        if (!shipPositions.contains(coordinate)) {
            notifyStateChange("MISS");
            return HitResult.MISS;
        }

        shipPositions.remove(coordinate);

        if (shipPositions.isEmpty()) {
            gameOver = true;
            winner = "Opponent";
            notifyStateChange("HIT");
            notifyStateChange("GAME_OVER");
            return HitResult.SUNK;
        }

        notifyStateChange("HIT");
        return HitResult.HIT;
    }

    public GameState getGameState() {
        return new GameState(
                new ArrayList<>(shipPositions),
                new ArrayList<>(attackPositions),
                gameOver,
                winner
        );
    }

    public void notifyStateChange(String event) {
        setChanged();
        notifyObservers(new StateChange(event, getGameState()));
    }

    private void validateCoordinate(String coordinate) {
        if (coordinate == null || coordinate.trim().isEmpty()) {
            throw new IllegalArgumentException("Coordinate must not be null or empty");
        }
    }
}

enum HitResult {
    HIT,
    MISS,
    SUNK
}

final class GameState {
    private final List<String> remainingShips;
    private final List<String> attacksMade;
    private final boolean gameOver;
    private final String winner;

    public GameState(
            List<String> remainingShips,
            List<String> attacksMade,
            boolean gameOver,
            String winner
    ) {
        this.remainingShips = Collections.unmodifiableList(new ArrayList<>(remainingShips));
        this.attacksMade = Collections.unmodifiableList(new ArrayList<>(attacksMade));
        this.gameOver = gameOver;
        this.winner = winner;
    }

    public List<String> getRemainingShips() {
        return remainingShips;
    }

    public List<String> getAttacksMade() {
        return attacksMade;
    }

    public boolean isGameOver() {
        return gameOver;
    }

    public String getWinner() {
        return winner;
    }
}

final class StateChange {
    private final String event;
    private final GameState gameState;

    public StateChange(String event, GameState gameState) {
        this.event = event;
        this.gameState = gameState;
    }

    public String getEvent() {
        return event;
    }

    public GameState getGameState() {
        return gameState;
    }
}
