import java.util.*;

class StringProcessor {

    public static Map<String, Object> processString(String input) {
        Map<String, Object> results = new LinkedHashMap<>();

        String reversed = new StringBuilder(input).reverse().toString();
        results.put("reversedString", reversed);

        StringBuilder wordsReversed = new StringBuilder();
        int wordCount = 0;
        long charCount = 0L;
        int wordStart = -1;

        for (int i = 0; i < input.length(); i++) {
            char current = input.charAt(i);

            if (Character.isWhitespace(current)) {
                if (wordStart != -1) {
                    wordsReversed.append(
                        new StringBuilder(input.substring(wordStart, i)).reverse()
                    );
                    wordCount++;
                    wordStart = -1;
                }
                wordsReversed.append(current);
            } else {
                charCount++;
                if (wordStart == -1) {
                    wordStart = i;
                }
            }
        }

        if (wordStart != -1) {
            wordsReversed.append(
                new StringBuilder(input.substring(wordStart)).reverse()
            );
            wordCount++;
        }

        results.put("wordsReversed", wordsReversed.toString());
        results.put("wordCount", wordCount);
        results.put("charCount", charCount);

        return results;
    }
}

