import java.util.*;

class StringProcessor {

    public static Map<String, Object> processString(String input) {
        if (input == null) {
            throw new IllegalArgumentException("Input string cannot be null");
        }

        Map<String, Object> results = new LinkedHashMap<>();

        String reversed = new StringBuilder(input).reverse().toString();
        results.put("reversedString", reversed);

        StringBuilder wordsReversed = new StringBuilder(input.length());
        int wordCount = 0;
        long charCount = 0;
        int index = 0;

        while (index < input.length()) {
            char current = input.charAt(index);

            if (Character.isWhitespace(current)) {
                wordsReversed.append(current);
                index++;
            } else {
                int start = index;
                while (index < input.length() &&
                       !Character.isWhitespace(input.charAt(index))) {
                    charCount++;
                    index++;
                }

                String word = input.substring(start, index);
                wordsReversed.append(new StringBuilder(word).reverse());
                wordCount++;
            }
        }

        results.put("wordsReversed", wordsReversed.toString());
        results.put("wordCount", wordCount);
        results.put("charCount", charCount);

        return results;
    }
}

