import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public class KeyValueStore<K, V> {
    private final ConcurrentHashMap<K, V> values = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, LongAdder> accessCounts =
            new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, AtomicLong> lastAccessTimes =
            new ConcurrentHashMap<>();

    public void put(K key, V value) {
        requireNonNullKey(key);
        values.put(key, value);
    }

    public V get(K key) {
        requireNonNullKey(key);

        accessCounts
                .computeIfAbsent(key, ignored -> new LongAdder())
                .increment();

        long now = System.currentTimeMillis();
        lastAccessTimes
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .updateAndGet(previous -> Math.max(previous, now));

        return values.get(key);
    }

    public long getAccessCount(K key) {
        requireNonNullKey(key);

        LongAdder counter = accessCounts.get(key);
        return counter == null ? 0L : counter.sum();
    }

    public long getLastAccessTime(K key) {
        requireNonNullKey(key);

        AtomicLong lastAccess = lastAccessTimes.get(key);
        return lastAccess == null ? 0L : lastAccess.get();
    }

    private void requireNonNullKey(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key must not be null");
        }
    }
}

