import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

public class KeyValueStore<K, V> {
    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, Long> accessCounts = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, Long> lastAccessTimes = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<Class<?>, Integer> typeCounts = new ConcurrentHashMap<>();

    public void put(K key, V value) {
        validateKey(key);

        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }

        synchronized (typeCounts) {
            V previousValue = store.put(key, value);

            if (previousValue != null) {
                decrementTypeCount(previousValue.getClass());
            }

            typeCounts.merge(value.getClass(), 1, Integer::sum);
        }
    }

    public V get(K key) {
        validateKey(key);

        accessCounts.merge(key, 1L, Long::sum);
        lastAccessTimes.put(key, System.currentTimeMillis());

        return store.get(key);
    }

    public long getAccessCount(K key) {
        validateKey(key);
        return accessCounts.getOrDefault(key, 0L);
    }

    public long getLastAccessTime(K key) {
        validateKey(key);
        return lastAccessTimes.getOrDefault(key, 0L);
    }

    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        return typeCounts.getOrDefault(type, 0);
    }

    private void decrementTypeCount(Class<?> type) {
        typeCounts.computeIfPresent(type, (key, count) ->
                count == 1 ? null : count - 1
        );
    }

    private void validateKey(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
    }
}

