import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.LongAdder;

public class KeyValueStore<K, V> {
    private static final Object NULL_VALUE = new Object();

    private final ConcurrentMap<K, Object> values = new ConcurrentHashMap<>();
    private final ConcurrentMap<K, LongAdder> accessCounts = new ConcurrentHashMap<>();
    private final ConcurrentMap<K, Long> lastAccessTimes = new ConcurrentHashMap<>();
    private final ConcurrentMap<Class<?>, LongAdder> typeCounts = new ConcurrentHashMap<>();

    public void put(K key, V value) {
        validateKey(key);

        Object storedValue = value == null ? NULL_VALUE : value;
        Object previousValue = values.put(key, storedValue);

        synchronized (typeCounts) {
            if (previousValue != null && previousValue != NULL_VALUE) {
                decrementTypeCount(previousValue.getClass());
            }
            if (value != null) {
                incrementTypeCount(value.getClass());
            }
        }
    }

    public void putAll(Map<? extends K, ? extends V> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }

        for (K key : entries.keySet()) {
            validateKey(key);
        }

        for (Map.Entry<? extends K, ? extends V> entry : entries.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    @SuppressWarnings("unchecked")
    public V get(K key) {
        validateKey(key);

        accessCounts.computeIfAbsent(key, ignored -> new LongAdder()).increment();
        lastAccessTimes.put(key, System.currentTimeMillis());

        Object value = values.get(key);
        return value == NULL_VALUE ? null : (V) value;
    }

    public long getAccessCount(K key) {
        validateKey(key);

        LongAdder counter = accessCounts.get(key);
        return counter == null ? 0L : counter.sum();
    }

    public long getLastAccessTime(K key) {
        validateKey(key);
        return lastAccessTimes.getOrDefault(key, 0L);
    }

    public long getTypeCount(Class<?> type) {
        if (type == null) {
            return 0L;
        }

        LongAdder counter = typeCounts.get(type);
        return counter == null ? 0L : counter.sum();
    }

    public List<K> findKeysByType(Class<?> type) {
        if (type == null) {
            return Collections.emptyList();
        }

        List<K> result = new ArrayList<>();
        for (Map.Entry<K, Object> entry : values.entrySet()) {
            Object value = entry.getValue();
            if (value != NULL_VALUE && value.getClass().equals(type)) {
                result.add(entry.getKey());
            }
        }
        return result;
    }

    public Map<String, Object> computeStatistics() {
        Map<String, Object> statistics = new LinkedHashMap<>();

        statistics.put("totalEntries", values.size());

        K keyWithMaxAccess = null;
        long maxAccess = -1L;

        for (K key : values.keySet()) {
            long accessCount = getAccessCount(key);
            if (accessCount > maxAccess) {
                maxAccess = accessCount;
                keyWithMaxAccess = key;
            }
        }

        statistics.put("keyWithMaxAccess", keyWithMaxAccess);
