class TwoSatSolver {
    private final Map<Integer, List<Integer>> graph;
    private final Map<Integer, List<Integer>> reverseGraph;
    private final Set<Integer> variables;
    private final Map<Integer, Integer> finishingTimes;
    private int finishingTime;

    public TwoSatSolver() {
        graph = new HashMap<>();
        reverseGraph = new HashMap<>();
        variables = new HashSet<>();
        finishingTimes = new HashMap<>();
        finishingTime = 0;
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        addNode(a);
        addNode(b);
        addNode(-a);
        addNode(-b);

        addEdge(-a, b);
        addEdge(-b, a);
    }

    private void addNode(int node) {
        graph.computeIfAbsent(node, key -> new ArrayList<>());
        reverseGraph.computeIfAbsent(node, key -> new ArrayList<>());
    }

    private void addEdge(int from, int to) {
        addNode(from);
        addNode(to);

        graph.get(from).add(to);
        reverseGraph.get(to).add(from);
    }

    public boolean isSatisfiable() {
        finishingTimes.clear();
        finishingTime = 0;

        Set<Integer> visited = new HashSet<>();

        for (int node : reverseGraph.keySet()) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited);
            }
        }

        // The second pass and strongly connected component validation
        // are not implemented yet.
        return true;
    }

    private void dfsReverse(int node, Set<Integer> visited) {
        visited.add(node);

        for (int neighbor : reverseGraph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                dfsReverse(neighbor, visited);
            }
        }

        finishingTimes.put(node, finishingTime++);
    }
}

