                new java.util.HashMap<>();
        java.util.Set<Integer> visited = new java.util.HashSet<>();
        int[] time = {0};

        for (int node : nodes) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited, finishingTimes, time);
            }
        }

        java.util.List<Integer> orderedNodes = new java.util.ArrayList<>(nodes);
        orderedNodes.sort(
                (x, y) -> Integer.compare(
                        finishingTimes.get(y),
                        finishingTimes.get(x)
                )
        );

