import java.util.*;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        if (graph == null || graph.length == 0) {
            throw new IllegalArgumentException("Graph must not be null or empty.");
        }

        int n = graph.length;
        for (int[] row : graph) {
            if (row == null || row.length != n) {
                throw new IllegalArgumentException("Graph must be a square matrix.");
            }
        }

        if (source < 0 || source >= n) {
            throw new IllegalArgumentException("Source vertex is out of range.");
        }

        int[] distances = new int[n];
        int[] previous = new int[n];
        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(previous, -1);
        distances[source] = 0;

        PriorityQueue<Vertex> queue =
                new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        queue.offer(new Vertex(source, 0));

        while (!queue.isEmpty()) {
            Vertex current = queue.poll();

            if (current.distance != distances[current.index]) {
                continue;
            }

