            visitedCount++;

            for (int neighbor = 0; neighbor < n; neighbor++) {
                int weight = graph[current.index][neighbor];

                // A zero value represents the absence of an edge.
                if (weight == 0 || processed[neighbor]) {
                    continue;
                }

                if (current.distance > Integer.MAX_VALUE - weight) {
                    continue;
                }

                int newDistance = current.distance + weight;
                if (newDistance < distances[neighbor]) {
                    distances[neighbor] = newDistance;
                    prev[neighbor] = current.index;
                    queue.offer(new Vertex(neighbor, newDistance));
                }
            }
        }

        List<List<Integer>> paths = new ArrayList<>();
        for (int vertex = 0; vertex < n; vertex++) {
            paths.add(buildPath(prev, source, vertex));
        }

        int maxDistance = 0;
        for (int distance : distances) {
            if (distance != Integer.MAX_VALUE) {
                maxDistance = Math.max(maxDistance, distance);
            }
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("distances", distances);
        result.put("paths", paths);
        result.put("visitedCount", visitedCount);
        result.put("maxDistance", maxDistance);

        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        List<Integer> path = new ArrayList<>();

        if (target < 0 || target >= prev.length) {
            return path;
        }

        int current = target;
        while (current != -1) {
            path.add(current);

            if (current == source) {
                Collections.reverse(path);
                return path;
            }

            current = prev[current];
        }

        return new ArrayList<>();
    }

    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
